draw(p,vp,eye,pass){
  const g=this.gl,foliage=p===this.main&&(pass===0||pass===3)&&this.state.specializedFoliage!==false;
  if(foliage){this.stateUniforms(this.foliage,vp,eye,pass);this.sampler(this.foliage,'uShadowMap',0,this.shadowTarget.tex);}
  this.stateUniforms(p,vp,eye,pass);
  if(p===this.main){this.sampler(p,'uShadowMap',0,this.shadowTarget.tex);this.sampler(p,'uReflectionMap',1,pass===3?this.dummy:this.reflectTarget.tex);this.sampler(p,'uAtlas',2,this.atlas||this.dummy);this.sampler(p,'uMaterials',3,this.materials||this.dummy);this.sampler(p,'uShoreDistance',4,this.shoreTexture);}
  const ceramic=p===this.main&&(pass===0||pass===3)&&this.state.specializedCeramic!==false;
  if(ceramic){this.stateUniforms(this.ceramic,vp,eye,pass);this.sampler(this.ceramic,'uShadowMap',0,this.shadowTarget.tex);this.sampler(this.ceramic,'uReflectionMap',1,pass===3?this.dummy:this.reflectTarget.tex);this.sampler(this.ceramic,'uAtlas',2,this.atlas||this.dummy);this.sampler(this.ceramic,'uMaterials',3,this.materials||this.dummy);this.sampler(this.ceramic,'uShoreDistance',4,this.shoreTexture);}
  const cached=this.visibleScene(vp,pass===1?0:pass);
  // stateUniforms binds its program; ceramic setup was the last binding above.
  let calls=0,blending=false,index=0,active=ceramic?this.ceramic:p;try{for(const{b,record,ranges,pageRange208}of cached.drawItems){
   if(index===cached.drawClearStart&&(pass===0||pass===3)){this.people?.draw(vp,eye,pass);if(this.state.skyAfterOpaque!==false)this.sky(vp,eye,true);}
   if(index++===cached.drawClearStart&&(pass===0||pass===3)){
    const glass=this.glass;this.stateUniforms(glass,vp,eye,pass);active=glass;
    this.sampler(glass,'uShadowMap',0,this.shadowTarget.tex);this.sampler(glass,'uReflectionMap',1,pass===3?this.dummy:this.reflectTarget.tex);this.sampler(glass,'uAtlas',2,this.atlas||this.dummy);this.sampler(glass,'uMaterials',3,this.materials||this.dummy);this.sampler(glass,'uShoreDistance',4,this.shoreTexture);
    g.enable(g.BLEND);g.blendFunc(g.SRC_ALPHA,g.ONE_MINUS_SRC_ALPHA);g.depthMask(false);blending=true;
   }
   if(blending){const next=b.uniformMaterial===47?this.membrane:this.glass;if(active!==next){this.stateUniforms(next,vp,eye,pass);this.sampler(next,'uShadowMap',0,this.shadowTarget.tex);this.sampler(next,'uReflectionMap',1,pass===3?this.dummy:this.reflectTarget.tex);this.sampler(next,'uAtlas',2,this.atlas||this.dummy);this.sampler(next,'uMaterials',3,this.materials||this.dummy);this.sampler(next,'uShoreDistance',4,this.shoreTexture);active=next;}}
   if((foliage||ceramic)&&!blending){const next=ceramic&&b.uniformMaterial===25?this.ceramic:foliage&&b.foliageIsotropic?this.foliage:p;if(active!==next){g.useProgram(next.p);active=next;}}
   g.bindVertexArray(record.vao);
   if(pageRange208){g.drawElementsInstanced(g.TRIANGLES,pageRange208[1],g.UNSIGNED_SHORT,pageRange208[0]*2,1);calls++;}
   else if(ranges){for(const[first,count]of ranges){if(b.resource.indexBuffer)g.drawElementsInstanced(g.TRIANGLES,count,b.resource.indexType==='uint16'?g.UNSIGNED_SHORT:g.UNSIGNED_INT,first*(b.resource.indexType==='uint16'?2:4),record.count);else g.drawArraysInstanced(g.TRIANGLES,first,count,record.count);calls++;}}
   else{if(b.resource.indexBuffer)g.drawElementsInstanced(g.TRIANGLES,b.vertexCount,b.resource.indexType==='uint16'?g.UNSIGNED_SHORT:g.UNSIGNED_INT,b.resource.indexByteOffset208||0,record.count);else g.drawArraysInstanced(g.TRIANGLES,0,b.vertexCount,record.count);calls++;}
  }if(cached.drawClearStart===cached.drawItems.length&&(pass===0||pass===3)){this.people?.draw(vp,eye,pass);if(this.state.skyAfterOpaque!==false)this.sky(vp,eye,true);}
  }finally{if(blending){g.depthMask(true);g.disable(g.BLEND);}g.bindVertexArray(null);}
  if(pass===0){const people=this.people?.active&&this.people.mask?this.people.metrics:null;Object.assign(this.stats,{drawnInstances:cached.submitted+(people?.instances||0),drawnTriangles:cached.triangles+(people?.triangles||0),detailCulled:cached.culled,drawCalls:calls+(people?.mainCalls||0)+(people?.shadowCalls||0),people});}
 }
